  readonly analytics = getAnalyticsSettings(connection);
  readonly design = design;
  readonly pageSize = design.groupedBy ? GROUPING_ROWS : design.resultsPerPage;
  readonly resultLanguage = contentLanguageTag(connection.language);
  readonly isDemo = connection.source === 'demo' && connection.searchURL === demo.searchURL && connection.model === demo.model && this.resultLanguage === demo.language;
  readonly status = signal('Connecting to search…');
  readonly loadedResults = signal(0);
