    const batch = groupedPage(response, design.groupedBy, design.itemsPerGroup);
    renderKitGroupedPager(this.pagination?.nativeElement.querySelector('[data-grouped-pager]') ?? null, batch);
    const grouped = batch ? groupHeadings(mapped, response, this.isDemo ? facetLabels : {}) : mapped;
